import { doc, getDoc } from "firebase/firestore";
import { httpsCallable } from "firebase/functions";
import { db, functions } from "./firebase";

/** Professor's Notes (INSTRUCTIONS.md §6): cached in aiLore/{dexId}, generated by a Cloud Function. */

export interface AiNote {
  text: string;
  model?: string;
}

export async function getCachedNote(dexId: number): Promise<AiNote | null> {
  const snap = await getDoc(doc(db, "aiLore", String(dexId)));
  if (!snap.exists()) return null;
  const data = snap.data();
  return typeof data.text === "string" ? { text: data.text, model: data.model } : null;
}

const callProfessor = httpsCallable<{ dexId: number }, AiNote>(functions, "professorNotes", { timeout: 120_000 });

export async function requestNote(dexId: number): Promise<AiNote> {
  const res = await callProfessor({ dexId });
  return res.data;
}

/** Human-readable message for a callable failure. */
export function professorError(err: unknown): string {
  const code = (err as { code?: string })?.code ?? "";
  if (code.endsWith("unauthenticated")) return "Sign in so the Professor knows who's asking.";
  if (code.endsWith("resource-exhausted")) return "The Professor is already writing this one. Try again in a moment.";
  if (code.endsWith("not-found") || code.endsWith("internal") || code.endsWith("unavailable"))
    return "The Professor is away from the lab right now (Cloud Function not reachable).";
  return "The Professor couldn't write a note this time.";
}
